"""FIT file parser using `fitparse`.

Extracts a session-level summary plus per-second records (power, cadence,
HR, GPS). Lazy-imports fitparse so the module is loadable without the
dependency installed.
"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Iterator


def _semicircles_to_deg(value: int | None) -> float | None:
    if value is None:
        return None
    return value * (180.0 / 2**31)


def _ensure_fitparse():
    try:
        import fitparse  # type: ignore
    except ImportError as e:
        raise RuntimeError(
            "fitparse not installed. Run: pip install --user 'fitparse>=1.2,<2'"
        ) from e
    return fitparse


def parse(path: str | Path) -> dict[str, Any]:
    fitparse = _ensure_fitparse()
    fit = fitparse.FitFile(str(path))

    session = _first_session(fit)
    records = list(_iter_records(fit))

    summary = {
        "fit_path": str(path),
        "start_time": _iso(session.get("start_time")) if session else None,
        "total_elapsed_time_s": _f(session, "total_elapsed_time"),
        "total_timer_time_s": _f(session, "total_timer_time"),
        "total_distance_m": _f(session, "total_distance"),
        "total_ascent_m": _f(session, "total_ascent"),
        "total_descent_m": _f(session, "total_descent"),
        "avg_speed_ms": _f(session, "avg_speed"),
        "max_speed_ms": _f(session, "max_speed"),
        "avg_power_w": _f(session, "avg_power"),
        "max_power_w": _f(session, "max_power"),
        "normalized_power_w": _f(session, "normalized_power"),
        "training_stress_score": _f(session, "training_stress_score"),
        "intensity_factor": _f(session, "intensity_factor"),
        "avg_heart_rate": _f(session, "avg_heart_rate"),
        "max_heart_rate": _f(session, "max_heart_rate"),
        "avg_cadence": _f(session, "avg_cadence"),
        "max_cadence": _f(session, "max_cadence"),
        "total_calories": _f(session, "total_calories"),
        "sport": session.get("sport") if session else None,
        "sub_sport": session.get("sub_sport") if session else None,
        "record_count": len(records),
    }
    return {"summary": summary, "records": records}


def _first_session(fit) -> dict | None:
    for msg in fit.get_messages("session"):
        return {f.name: f.value for f in msg.fields}
    return None


def _iter_records(fit) -> Iterator[dict]:
    for msg in fit.get_messages("record"):
        d: dict[str, Any] = {}
        for f in msg.fields:
            v = f.value
            if f.name in ("position_lat", "position_long"):
                v = _semicircles_to_deg(v) if isinstance(v, int) else v
            elif f.name == "timestamp":
                v = _iso(v)
            d[f.name] = v
        yield d


def _f(session: dict | None, key: str) -> float | None:
    if not session:
        return None
    v = session.get(key)
    if v is None:
        return None
    try:
        return float(v)
    except (TypeError, ValueError):
        return None


def _iso(dt) -> str | None:
    if dt is None:
        return None
    try:
        return dt.isoformat()
    except AttributeError:
        return str(dt)


if __name__ == "__main__":
    import argparse
    import json
    import sys

    p = argparse.ArgumentParser(description="Parse a FIT file")
    p.add_argument("fit", help="Path to .fit file")
    p.add_argument(
        "--summary-only", action="store_true", help="Skip per-second records"
    )
    args = p.parse_args()

    out = parse(args.fit)
    if args.summary_only:
        out = {"summary": out["summary"]}
    json.dump(out, sys.stdout, indent=2, default=str)
    sys.stdout.write("\n")

"""Wahoo OAuth2 token management.

Loads client credentials from env (WAHOO_CLIENT_ID, WAHOO_CLIENT_SECRET,
WAHOO_REDIRECT_URI), persists tokens to ~/.openclaw/secrets/wahoo_tokens.json
(mode 0600), and auto-refreshes the access token when the API returns 401.
"""

from __future__ import annotations

import json
import os
import time
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Optional

OAUTH_AUTHORIZE_URL = "https://api.wahooligan.com/oauth/authorize"
OAUTH_TOKEN_URL = "https://api.wahooligan.com/oauth/token"

DEFAULT_SCOPES = "workouts_read offline_data user_read"
DEFAULT_REDIRECT_URI = "https://localhost:8080/"

TOKENS_PATH = Path(os.path.expanduser("~/.openclaw/secrets/wahoo_tokens.json"))
DEFAULT_ENV_FILE = Path(os.path.expanduser("~/.openclaw/secrets/wahoo.env"))


class WahooAuthError(RuntimeError):
    pass


def _maybe_load_dotenv() -> None:
    """Populate WAHOO_* env vars from ~/.openclaw/secrets/wahoo.env (or
    $WAHOO_ENV_FILE) if they aren't already set. No-op if the file is missing
    or all needed vars are already in os.environ. Lets agents (e.g. Puck)
    invoke the skill without having to source the env file in their shell.
    """
    if os.environ.get("WAHOO_CLIENT_ID") and os.environ.get("WAHOO_CLIENT_SECRET"):
        return
    env_path = Path(
        os.environ.get("WAHOO_ENV_FILE", str(DEFAULT_ENV_FILE))
    ).expanduser()
    if not env_path.exists():
        return
    try:
        text = env_path.read_text()
    except OSError:
        return
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[7:].lstrip()
        if "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        if key.startswith("WAHOO_") and key not in os.environ:
            os.environ[key] = value


def _client_credentials() -> tuple[str, str, str, str]:
    _maybe_load_dotenv()
    client_id = os.environ.get("WAHOO_CLIENT_ID")
    client_secret = os.environ.get("WAHOO_CLIENT_SECRET")
    if not client_id or not client_secret:
        raise WahooAuthError(
            "Set WAHOO_CLIENT_ID and WAHOO_CLIENT_SECRET in env, in "
            "~/.openclaw/secrets/wahoo.env, or in ~/.clawdbot/clawdbot.json"
        )
    redirect_uri = os.environ.get("WAHOO_REDIRECT_URI", DEFAULT_REDIRECT_URI)
    scopes = os.environ.get("WAHOO_SCOPES", DEFAULT_SCOPES)
    return client_id, client_secret, redirect_uri, scopes


def authorize_url() -> str:
    client_id, _, redirect_uri, scopes = _client_credentials()
    qs = urllib.parse.urlencode(
        {
            "client_id": client_id,
            "redirect_uri": redirect_uri,
            "scope": scopes,
            "response_type": "code",
        }
    )
    return f"{OAUTH_AUTHORIZE_URL}?{qs}"


def _post_form(url: str, data: dict) -> dict:
    body = urllib.parse.urlencode(data).encode("utf-8")
    req = urllib.request.Request(
        url,
        data=body,
        method="POST",
        headers={"Content-Type": "application/x-www-form-urlencoded"},
    )
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            payload = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        detail = e.read().decode("utf-8", errors="replace")
        raise WahooAuthError(f"OAuth HTTP {e.code}: {detail}") from None
    return payload


def exchange_code(code: str) -> dict:
    client_id, client_secret, redirect_uri, _ = _client_credentials()
    payload = _post_form(
        OAUTH_TOKEN_URL,
        {
            "grant_type": "authorization_code",
            "code": code,
            "client_id": client_id,
            "client_secret": client_secret,
            "redirect_uri": redirect_uri,
        },
    )
    _save_tokens(payload)
    return payload


def refresh(refresh_token: Optional[str] = None) -> dict:
    client_id, client_secret, _, _ = _client_credentials()
    if refresh_token is None:
        tokens = load_tokens()
        refresh_token = tokens.get("refresh_token")
    if not refresh_token:
        raise WahooAuthError(
            "No refresh_token on file — re-run scripts/oauth_setup.py"
        )
    payload = _post_form(
        OAUTH_TOKEN_URL,
        {
            "grant_type": "refresh_token",
            "refresh_token": refresh_token,
            "client_id": client_id,
            "client_secret": client_secret,
        },
    )
    _save_tokens(payload)
    return payload


def _save_tokens(payload: dict) -> None:
    TOKENS_PATH.parent.mkdir(parents=True, exist_ok=True)
    record = dict(payload)
    if "expires_in" in record:
        record["expires_at"] = int(time.time()) + int(record["expires_in"])
    with open(TOKENS_PATH, "w") as f:
        json.dump(record, f, indent=2)
    os.chmod(TOKENS_PATH, 0o600)


def load_tokens() -> dict:
    if not TOKENS_PATH.exists():
        return {}
    with open(TOKENS_PATH) as f:
        return json.load(f)


def access_token() -> str:
    """Return a valid access token, refreshing if expired."""
    env_token = os.environ.get("WAHOO_ACCESS_TOKEN")
    if env_token and not TOKENS_PATH.exists():
        return env_token
    tokens = load_tokens()
    token = tokens.get("access_token")
    expires_at = tokens.get("expires_at", 0)
    if not token:
        raise WahooAuthError(
            "No access_token on file — run scripts/oauth_setup.py"
        )
    if expires_at and expires_at - 60 < time.time():
        tokens = refresh(tokens.get("refresh_token"))
        token = tokens["access_token"]
    return token


def _redacted_status() -> dict:
    """Return token-file metadata without exposing token values."""
    t = load_tokens()
    if not t:
        return {"present": False, "path": str(TOKENS_PATH)}
    expires_at = t.get("expires_at")
    return {
        "present": True,
        "path": str(TOKENS_PATH),
        "has_access_token": bool(t.get("access_token")),
        "has_refresh_token": bool(t.get("refresh_token")),
        "expires_at": expires_at,
        "expires_in_s": (expires_at - int(time.time())) if expires_at else None,
        "scope": t.get("scope"),
        "token_type": t.get("token_type"),
    }


if __name__ == "__main__":
    # Never dump raw tokens to stdout/logs. Print redacted status only.
    print(json.dumps(_redacted_status(), indent=2))
